Q: Switch case in a JavaScript function A: <p>Switch case statements do not produce a value on their own, they just decide which branch / case matches with your query and that is the one which needs to be executed. Therefore, you must return a value from your switch case statement using either one of two ways:</p>
<ol>
<li>using console.log(&quot;output&quot;) inside your cases, like:</li>
</ol>
<pre><code>switch(condition){ 
    case `your condition matching statement`
    console.log(&quot;your output value&quot;);
    break;
}
</code></pre>
<ol start="2">
<li>using return statements in your case blocks:</li>
</ol>
<pre><code>switch(condition){ 
    case `your condition matching statement`
    return &quot;your output value&quot;;
    // not in return there is no need of break as after the return statement your break block doesn't executes.
}
</code></pre>
<p>Also, in your code there are a few syntactical and logical errors like:</p>
<pre><code>// Source - https://stackoverflow.com/q/28972446
// Posted by Thomas Bengtsson, modified by community. See post 'Timeline' for change history
// Retrieved 2026-07-26, License - CC BY-SA 4.0

function fruitColor(fruit) {
    switch(color) { // passing the variable as &quot;color&quot; instead of &quot;fruit&quot;
        case &quot;apple&quot; : green; // having no return or console.log() statements for printing the output 
            break;
        case &quot;banana&quot; : yellow;
            break;
        case &quot;kiwi&quot; : green;
            break;
        case &quot;plum&quot; : red;
            break;
    }
}

var result = fruitColor(plum); // finally not printing the result variable
</code></pre>
<p>The above code should look like this in order to execute perfectly:</p>
<pre><code>function fruitColor(fruit) {
    switch(fruit) {
        case &quot;apple&quot; : 
            return &quot;red&quot;;

        case &quot;banana&quot; : 
            return &quot;yellow&quot;;

        case &quot;kiwi&quot; : 
            return &quot;green&quot;;

        case &quot;plum&quot; : 
            return &quot;red&quot;;

    }
}

var result = fruitColor(&quot;plum&quot;);
console.log(result); 

//or 

console.log(fruitColor(&quot;banana&quot;));
</code></pre>
<p>or like the following:</p>
<pre><code>function fruitColor(fruit) {
  switch (fruit) {
    case &quot;apple&quot;:
      console.log(&quot;red&quot;);
      break;
    case &quot;banana&quot;:
      console.log(&quot;yellow&quot;);
      break;
    case &quot;kiwi&quot;:
      console.log(&quot;green&quot;);
      break;
    case &quot;plum&quot;:
      console.log(&quot;red&quot;);
      break;
  }
}

var result = fruitColor(&quot;plum&quot;);
console.log(result);
</code></pre>
